<?php defined('ABSPATH') || exit; $view=studio_view();$user=wp_get_current_user();$admin=current_user_can('manage_options');$writer=current_user_can('edit_posts');
function studio_header($view,$writer){ ?>
<header class="topbar"><a class="brand" href="<?php echo esc_url(home_url('/')); ?>"><span class="brandmark">B</span><span>Hệ Thống Blog/ CMS<small>BLOG & CMS</small></span></a><nav class="topnav" aria-label="Điều hướng chính"><a href="<?php echo esc_url(home_url('/')); ?>" class="<?php echo !$view?'selected':''; ?>">Khám phá</a><a href="<?php echo esc_url(studio_url('topics')); ?>">Chủ đề</a><a href="<?php echo esc_url(studio_url('about')); ?>">Giới thiệu</a><a class="btn small" href="<?php echo esc_url(studio_url($writer?'dashboard':'login')); ?>"><?php echo $writer?'Không gian quản trị ↗':'Đăng nhập ↗'; ?></a></nav></header>
