function studio_card($post,$i=0){$cats=get_the_category($post->ID); ?>
<article class="post-card"><a href="<?php echo esc_url(get_permalink($post)); ?>" class="card-art tone-<?php echo (int)($i%3); ?> <?php echo has_post_thumbnail($post)?'has-image':''; ?>" aria-label="<?php echo esc_attr(get_the_title($post)); ?>"><?php if(has_post_thumbnail($post)) echo get_the_post_thumbnail($post,'large');else echo '<span class="glyph" aria-hidden="true">'.['{ }','Aa','↗'][$i%3].'</span>'; ?></a><div class="card-body"><span class="tag"><?php echo esc_html($cats?$cats[0]->name:'Bài viết'); ?></span><h3><a href="<?php echo esc_url(get_permalink($post)); ?>"><?php echo esc_html(get_the_title($post)); ?></a></h3><p><?php echo esc_html(wp_trim_words(get_the_excerpt($post),25)); ?></p></div><div class="card-meta"><span><?php echo esc_html(get_the_author_meta('display_name',$post->post_author)); ?> · <?php echo esc_html(get_the_date('d.m.Y',$post)); ?></span><a href="<?php echo esc_url(get_permalink($post)); ?>">Đọc tiếp ↗</a></div></article>
<?php }
function studio_post_table($posts){ ?><div class="table-scroll"><table><thead><tr><th>Bài viết</th><th>Danh mục</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><?php foreach($posts as $item): ?><tr><td><strong><?php echo esc_html($item->post_title); ?></strong><p><?php echo esc_html(get_the_date('d/m/Y',$item)); ?></p></td><td><?php echo esc_html(implode(', ',wp_get_post_categories($item->ID,['fields'=>'names']))); ?></td><td><span class="badge <?php echo $item->post_status==='publish'?'':'off'; ?>"><?php echo $item->post_status==='publish'?'Đã xuất bản':'Bản nháp'; ?></span></td><td><div class="actions"><a class="btn small light" href="<?php echo esc_url(studio_url('edit',['id'=>$item->ID])); ?>">Sửa</a><a class="mini" href="<?php echo esc_url(get_permalink($item)); ?>">Xem ↗</a><?php if(current_user_can('delete_post',$item->ID)): ?><form method="post" class="inline" data-confirm="Chuyển bài viết này vào thùng rác?"><?php studio_form_fields('trash_post'); ?><input type="hidden" name="post_id" value="<?php echo (int)$item->ID; ?>"><button class="btn small danger">Xóa</button></form><?php endif; ?></div></td></tr><?php endforeach; ?><?php if(!$posts): ?><tr><td colspan="4">Chưa có bài viết. Hãy tạo bài viết đầu tiên.</td></tr><?php endif; ?></tbody></table></div><?php }
?><!doctype html><html <?php language_attributes(); ?>><head><meta charset="<?php bloginfo('charset'); ?>"><meta name="viewport" content="width=device-width, initial-scale=1"><?php wp_head(); ?></head><body <?php body_class(); ?>><?php wp_body_open(); ?><div class="wrap"><?php studio_header($view,$writer); ?>
<?php if(in_array($view,['dashboard','posts','edit','categories','users','database','monitoring','logs'],true)):
 $nav=[['dashboard','◫','Tổng quan'],['posts','▤','Bài viết'],['categories','▦','Danh mục']];if($admin)$nav=array_merge($nav,[['users','♧','Người dùng'],['database','▱','Cơ sở dữ liệu'],['monitoring','⌁','Giám sát'],['logs','≡','Nhật ký']]);
 $titles=['dashboard'=>'Không gian quản trị','posts'=>'Quản lý bài viết','edit'=>'Biên tập bài viết','categories'=>'Quản lý danh mục','users'=>'Người dùng','database'=>'Cơ sở dữ liệu','monitoring'=>'Giám sát hệ thống','logs'=>'Nhật ký truy cập'];
 $args=['post_type'=>'post','post_status'=>['publish','draft','pending','private'],'numberposts'=>50];if(!current_user_can('edit_others_posts'))$args['author']=$user->ID;
