 ?>
<div class="workspace"><aside class="sidebar"><div class="sidebar-label">Không gian làm việc</div><?php foreach($nav as [$slug,$icon,$label]): ?><a href="<?php echo esc_url(studio_url($slug)); ?>" class="<?php echo $view===$slug||($view==='edit'&&$slug==='posts')?'active':''; ?>"><span class="nav-icon" aria-hidden="true"><?php echo esc_html($icon); ?></span><?php echo esc_html($label); ?></a><?php endforeach; ?><div class="sidebar-label">Tài khoản</div><a href="<?php echo esc_url(home_url('/')); ?>">↗ Xem website</a><a href="<?php echo esc_url(wp_logout_url(home_url('/'))); ?>">↪ Đăng xuất</a><div class="sidebar-note">Xin chào, <strong><?php echo esc_html($user->display_name); ?></strong><br><span class="role"><?php echo $admin?'Quản trị viên':'Biên tập nội dung'; ?></span><br><br>Một nơi cho nội dung<br>và hoạt động hệ thống.</div></aside><main class="main"><div class="pagehead"><div><div class="eyebrow"><span class="dot"></span> CMS STUDIO / <?php echo esc_html(date_i18n('d.m.Y')); ?></div><h1><?php echo esc_html($titles[$view]); ?></h1><p>Nội dung và dữ liệu thật từ hệ thống Blog/CMS của bạn.</p></div><?php if(in_array($view,['dashboard','posts'],true)): ?><a class="btn" href="<?php echo esc_url(studio_url('edit')); ?>">＋ Viết bài mới</a><?php endif; ?></div>
<?php $notice=get_transient('studio_notice_'.$user->ID);if($notice){delete_transient('studio_notice_'.$user->ID);echo '<div class="notice '.($notice['error']?'error':'').'" role="status">'.esc_html($notice['text']).'</div>';}
if($view==='dashboard'): ?>
<div class="stats"><div class="stat"><span class="label">Bài đã xuất bản</span><b><?php echo (int)$counts->publish; ?></b><small>Nội dung đang hiển thị</small></div><div class="stat"><span class="label">Bản nháp</span><b><?php echo (int)$counts->draft; ?></b><small>Đang chờ hoàn thiện</small></div><div class="stat"><span class="label">Danh mục</span><b><?php echo count($categories); ?></b><small>Chủ đề của blog</small></div><div class="stat"><span class="label"><?php echo $admin?'Người dùng':'Bài của bạn'; ?></span><b><?php echo $admin?(int)count_users()['total_users']:count_user_posts($user->ID); ?></b><small><?php echo $admin?'Tài khoản trong WordPress':'Bài đã xuất bản'; ?></small></div></div>
<div class="split"><section class="hero-small"><div class="eyebrow">Nội dung tạo nên kết nối</div><h2>Một ý tưởng hay,<br>một bài viết mới.</h2><p>Viết, phân loại và xuất bản ngay tại đây.<br>Dữ liệu được lưu trong WordPress và MySQL.</p><a class="btn" href="<?php echo esc_url(studio_url('edit')); ?>">Bắt đầu viết ↗</a></section><section class="panel" style="margin:0"><h2>Hôm nay bạn muốn làm gì?</h2><div class="stack"><a href="<?php echo esc_url(studio_url('categories')); ?>">▦ Sắp xếp các chủ đề →</a><?php if($admin): ?><a href="<?php echo esc_url(studio_url('monitoring')); ?>">⌁ Theo dõi CPU, RAM và dịch vụ →</a><a href="<?php echo esc_url(studio_url('logs')); ?>">≡ Xem truy cập và lỗi HTTP →</a><?php endif; ?></div></section></div><section class="panel"><div class="section-head"><h2>Bài viết gần đây</h2><a class="mini" href="<?php echo esc_url(studio_url('posts')); ?>">Xem tất cả →</a></div><?php studio_post_table(array_slice($my_posts,0,6)); ?></section>
<?php elseif($view==='posts'): ?><section class="panel"><?php studio_post_table($my_posts); ?><p>Hiển thị tối đa 50 bài gần nhất. Bài xóa được chuyển vào thùng rác WordPress.</p></section>
<?php elseif($view==='edit'):
 $id=absint($_GET['id']??0);$editing=$id?get_post($id):null;if($id&&(!$editing||$editing->post_type!=='post'||!current_user_can('edit_post',$id)))wp_die('Không được sửa bài này.');
 $assigned=$id?wp_get_post_categories($id):[];
 ?><form method="post"><?php studio_form_fields('save_post'); ?><input type="hidden" name="post_id" value="<?php echo $id; ?>"><div class="split"><section class="panel" style="margin-top:0"><label class="field">Tiêu đề<input name="post_title" required maxlength="250" placeholder="Bắt đầu bằng một ý tưởng…" value="<?php echo esc_attr($editing?$editing->post_title:''); ?>"></label><label class="field">Nội dung<textarea class="editor" name="post_content" placeholder="Viết câu chuyện của bạn tại đây…"><?php echo esc_textarea($editing?$editing->post_content:''); ?></textarea></label><p>Hỗ trợ văn bản và HTML cơ bản như đoạn văn, tiêu đề, liên kết. Các khối WordPress cũ được giữ khi lưu.</p><label class="field">Mô tả ngắn<textarea name="post_excerpt" rows="3"><?php echo esc_textarea($editing?$editing->post_excerpt:''); ?></textarea></label></section><aside><section class="panel" style="margin-top:0"><h2>Xuất bản</h2><label class="field">Trạng thái<select name="post_status"><option value="draft" <?php selected($editing?$editing->post_status:'draft','draft'); ?>>Bản nháp</option><?php if(current_user_can('publish_posts')): ?><option value="publish" <?php selected($editing?$editing->post_status:'','publish'); ?>>Xuất bản</option><?php endif; ?></select></label><button class="btn" type="submit">Lưu bài viết</button></section><section class="panel"><h2>Danh mục</h2><?php foreach($categories as $c): ?><label class="check"><input type="checkbox" name="categories[]" value="<?php echo (int)$c->term_id; ?>" <?php checked(in_array($c->term_id,$assigned)); ?>> <?php echo esc_html($c->name); ?></label><?php endforeach; ?></section></aside></div></form>
<?php elseif($view==='categories'): ?><div class="split"><section class="panel" style="margin:0"><h2>Các chủ đề hiện có</h2><div class="table-scroll"><table><thead><tr><th>Danh mục</th><th>Bài viết</th><th>Thao tác</th></tr></thead><tbody><?php foreach($categories as $c): ?><tr><td><strong><?php echo esc_html($c->name); ?></strong><p><?php echo esc_html($c->description); ?></p></td><td><?php echo (int)$c->count; ?></td><td><?php if(current_user_can('manage_categories')): ?><a class="mini" href="<?php echo esc_url(studio_url('categories',['term'=>$c->term_id])); ?>">Sửa</a> <?php if($c->term_id!=get_option('default_category')): ?><form class="inline" method="post" data-confirm="Xóa danh mục? Bài viết không bị xóa."><?php studio_form_fields('delete_category'); ?><input name="term_id" type="hidden" value="<?php echo (int)$c->term_id; ?>"><button class="btn small danger">Xóa</button></form><?php endif; endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php if(current_user_can('manage_categories')):$term=isset($_GET['term'])?get_term(absint($_GET['term']),'category'):null;if(is_wp_error($term))$term=null; ?><form class="panel" style="margin:0" method="post"><?php studio_form_fields('save_category'); ?><h2><?php echo $term?'Sửa danh mục':'Thêm danh mục'; ?></h2><input type="hidden" name="term_id" value="<?php echo $term?(int)$term->term_id:0; ?>"><label class="field">Tên danh mục<input name="name" required value="<?php echo esc_attr($term?$term->name:''); ?>"></label><label class="field">Mô tả<textarea name="description"><?php echo esc_textarea($term?$term->description:''); ?></textarea></label><button class="btn">Lưu danh mục</button></form><?php endif; ?></div>
<?php elseif($view==='users'): ?><section class="panel"><h2>Thành viên của hệ thống</h2><div class="table-scroll"><table><thead><tr><th>Tài khoản</th><th>Email</th><th>Vai trò</th><th>Bài viết</th></tr></thead><tbody><?php foreach(get_users(['number'=>100]) as $member): ?><tr><td><strong><?php echo esc_html($member->display_name); ?></strong><p>@<?php echo esc_html($member->user_login); ?></p></td><td><?php echo esc_html($member->user_email); ?></td><td><span class="badge"><?php echo esc_html(implode(', ',$member->roles)); ?></span></td><td><?php echo (int)count_user_posts($member->ID); ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php if(current_user_can('create_users')): ?><form method="post" class="panel"><?php studio_form_fields('create_user'); ?><h2>Thêm thành viên</h2><div class="split"><div><label class="field">Tên đăng nhập<input name="username" required autocomplete="off"></label><label class="field">Tên hiển thị<input name="display_name" required></label><label class="field">Email<input type="email" name="email" required></label></div><div><label class="field">Vai trò<select name="role"><option value="author">Tác giả</option><option value="editor">Biên tập viên</option><option value="subscriber">Người theo dõi</option></select></label><label class="field">Mật khẩu mới<input name="password" type="password" required minlength="12" autocomplete="new-password"></label><p>Dùng ít nhất 12 ký tự. Không tái sử dụng mật khẩu quản trị.</p></div></div><button class="btn">Tạo tài khoản</button></form><?php endif; ?>
<?php elseif($view==='database'): global $wpdb;$table_names=$wpdb->get_col('SHOW TABLES'); ?><div class="stats"><div class="stat"><span class="label">Database</span><b style="font-size:25px"><?php echo esc_html(DB_NAME); ?></b><small>Kết nối từ WordPress</small></div><div class="stat"><span class="label">Số bảng</span><b><?php echo count($table_names); ?></b><small>Database hiện tại</small></div><div class="stat"><span class="label">MySQL</span><b style="font-size:25px"><?php echo esc_html($wpdb->db_version()); ?></b><small>Phiên bản máy chủ</small></div><div class="stat"><span class="label">Bài xuất bản</span><b><?php echo (int)$counts->publish; ?></b><small>Lưu trong <?php echo esc_html($wpdb->posts); ?></small></div></div><section class="panel"><h2>Bài viết đã lưu trong MySQL</h2><p>Dữ liệu đọc trực tiếp qua kết nối WordPress. Không hiển thị mật khẩu hoặc hàm băm tài khoản.</p><div class="table-scroll"><table><thead><tr><th>ID</th><th>Tiêu đề</th><th>Trạng thái</th><th>Cập nhật</th></tr></thead><tbody><?php foreach(get_posts(['numberposts'=>30,'post_status'=>['publish','draft']]) as $row): ?><tr><td><?php echo (int)$row->ID; ?></td><td><?php echo esc_html($row->post_title); ?></td><td><span class="badge"><?php echo esc_html($row->post_status); ?></span></td><td><?php echo esc_html($row->post_modified); ?></td></tr><?php endforeach; ?></tbody></table></div></section><section class="panel"><h2>Cấu trúc database</h2><div class="categories-list"><?php foreach($table_names as $t): ?><span class="pill"><?php echo esc_html($t); ?></span><?php endforeach; ?></div></section>
<?php elseif($view==='monitoring'): ?><div id="monitoring"><div class="toolbar"><p>Dữ liệu trực tiếp từ Prometheus · tự cập nhật mỗi 30 giây.</p><button id="refresh-metrics" class="btn small light">↻ Làm mới</button></div><div class="stats"><div class="stat"><span class="label">CPU máy chủ</span><b data-metric="cpu">—</b><small>Trung bình 5 phút</small></div><div class="stat"><span class="label">RAM sử dụng</span><b data-metric="ram">—</b><small>Bộ nhớ máy chủ</small></div><div class="stat"><span class="label">Kết nối MySQL</span><b data-metric="connections">—</b><small>Kết nối hiện tại</small></div><div class="stat"><span class="label">Yêu cầu HTTP / giây</span><b data-metric="requests">—</b><small>Toàn Nginx, có thể gồm scrape</small></div></div><div class="split"><section class="panel" style="margin:0"><h2>Lưu lượng HTTP</h2><p>Xu hướng 15 phút gần nhất · yêu cầu mỗi giây.</p><svg id="requests-chart" class="chart" viewBox="0 0 600 180" role="img" aria-label="Biểu đồ tốc độ yêu cầu HTTP"><text x="30" y="90" fill="#687772" font-size="14">Đang tải dữ liệu…</text></svg><p id="chart-range" class="mini"></p></section><section class="panel" style="margin:0"><h2>Trạng thái dịch vụ</h2><div id="services">Đang kiểm tra…</div></section></div><p id="metrics-message" class="load-message" role="status"></p></div>
<?php elseif($view==='logs'): ?><section class="panel"><h2>Truy vấn log tập trung</h2><p>Log Nginx trong 15 phút gần nhất, lấy trực tiếp từ Loki. Lọc theo định dạng access log để bỏ các bản ghi nội bộ của Loki.</p><div class="toolbar"><div class="tabs" role="group" aria-label="Bộ lọc nhật ký"><button class="pill active log-mode" data-mode="access">Log truy cập</button><button class="pill log-mode" data-mode="errors">Lỗi HTTP 404</button><button class="pill log-mode" data-mode="count">Số yêu cầu / 5 phút</button></div><button id="refresh-logs" class="btn small light">↻ Làm mới</button></div><p id="log-query" class="mini muted"></p><div id="log-output" class="log-output" aria-live="polite">Đang tải log…</div><p id="logs-message" class="load-message"></p></section>
